// The day's affirmation in Hebrew, for the country pages in Hebrew. Written by scripts/home_extras.py from data/affirmations-i18n/; do not edit.
(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"את לא צריכה להספיק הכול היום. הדבר הקטן הבא מספיק.\", \"עייפות זה לא כישלון. את עייפה כי את שם, יום אחרי יום.\", \"הכלים יכולים לחכות. מותר לך לשבת חמש דקות.\", \"דגני בוקר לארוחת ערב זה גם להאכיל את המשפחה.\", \"מנוחה היא לא משהו שצריך להרוויח. מותר לך לנוח עכשיו.\", \"יש ימים שבהם הניצחון הוא שכולם הגיעו בשלום לשעת השינה. זה ניצחון אמיתי.\", \"את עושה הרבה יותר ממה שמישהו רואה. אני רואה.\", \"בית מבולגן וילדים אהובים. זו עסקה טובה.\", \"ביום קשה, המיטב שלך נראה אחרת, והוא עדיין נחשב.\", \"נשימה עמוקה אחת. תורידי את הכתפיים. את מסתדרת יפה.\", \"זה בסדר להוריד את הרף היום. ביום אחר תוכלי להרים אותו שוב.\", \"לבקש עזרה זה כוח, לא חולשה.\", \"מותר לך להגיד לא לעוד דבר אחד.\", \"אם הרגשת היום בודדה, את לא האמא היחידה שהרגישה ככה. אנחנו הרבה.\", \"מגיעה לך חברה ששואלת מה שלומך ומחכה לתשובה.\", \"זה בסדר לפנות ראשונה. רוב האמהות מקוות שמישהי תעשה את זה.\", \"להרגיש שקופה לא אומר שאת לא חשובה. את חשובה מאוד.\", \"הרגשות שלך מובנים. את לא \\\"יותר מדי\\\".\", \"כאן את לא צריכה להסביר את היום הקשה שלך. אנחנו מבינות.\", \"הודעה לאמא אחרת שאומרת \\\"גם אני\\\" יכולה להפוך יום שלם.\", \"להאכיל, להחליף, לנדנד, ושוב מההתחלה. זו עבודה אמיתית, גם כשזה נראה כמו ישיבה במקום.\", \"את והתינוק שלך עוד לומדים להכיר זה את זה. אין לאן למהר.\", \"הימים עם תינוק חדש ארוכים. התקופה הזאת לא תימשך לנצח.\", \"אם כל מה שעשית היום היה לשמור על בן אדם קטן שבע וחם, עשית עבודה גדולה.\", \"את לא צריכה לחזור מהר לעצמך הקודמת. את יכולה פשוט להיות איפה שאת.\", \"לא משנה איך התינוק שלך ניזון, את דואגת לו. זה מה שחשוב.\", \"אפשר לישון מעט ולהיות מלאה באהבה באותו הזמן.\", \"תחזיקי את התינוק ותעזבי את הבית. הבית עוד יהיה פה.\", \"התקף זעם בסופר לא הופך אותך לאמא רעה. זה רק אומר שיש לך פעוט.\", \"הקטנים בודקים גבולות כי לידך הם מרגישים בטוחים.\", \"נשארת רגועה דקה אחת יותר מאתמול. זה נחשב.\", \"אם התפרצת, חיבוק ו\\\"סליחה\\\" מתקנים הרבה. וזה גם מלמד אותם משהו טוב.\", \"ידיים דביקות, קולות רמים, רגשות גדולים. את מגדלת בן אדם שלם.\", \"ה\\\"למה?\\\" החמישי בשעה הזאת הוא מוח קטן שגדל.\", \"לא צריך יום מושלם כדי ליצור זיכרון שמח.\", \"דלת שנטרקה היא לא סוף הסיפור. תשאירי את האור דלוק.\", \"אולי המתבגר שלך לא יגיד את זה, אבל הנוכחות היציבה שלך חשובה.\", \"להיות הרגועה בבית זו עבודה קשה. ואת עושה אותה.\", \"חלק מהשיחות הכי טובות קורות באוטו. פשוט תמשיכי לנסוע.\", \"הם מתרחקים כדי לגדול, לא כדי להשאיר אותך מאחור.\", \"את לא צריכה לדעת את כל התשובות. להקשיב זה חלק גדול מזה.\", \"ילדים גדולים עדיין צריכים אותך, רק בדרכים שקטות יותר.\", \"לסחוב הכול לבד דורש כוח שרוב האנשים לא רואים אף פעם.\", \"את אמא מספיק טובה לילד שלך. תמיד היית.\", \"זוג ידיים אחד, מאה משימות. תהיי עדינה עם עצמך.\", \"הילדים שלך לומדים, כשהם מסתכלים עלייך, איך נראה אדם חזק ואוהב.\", \"לקחת הפסקה זה לא לנטוש את העמדה. ככה ממשיכים.\", \"אף אחד לא סופר נקודות. אהבה ונוכחות, זה מה שחשוב.\", \"אבל ואהבה באים מאותו מקום. הגעגוע מראה כמה אהבת.\", \"אין לוח זמנים נכון לאבל. קחי את הזמן שאת צריכה.\", \"בימי השנה הקשים, תהיי עדינה עם עצמך כמו שהיית עם חברה.\", \"את יכולה לשאת עצב ועדיין לצחוק עם הילדים שלך. שניהם אמיתיים.\", \"אם איבדת הריון או תינוק, האובדן הזה אמיתי, וגם האהבה שלך.\", \"יש ימים שהאבל שקט ויש ימים שהוא רועש. שניהם בסדר.\", \"מעט כסף לא אומר מעט אהבה.\", \"הילדים שלך יזכרו את הזמן איתך יותר מהדברים שקנית.\", \"לשאול על עזרה עם החשבונות זה חכם, לא מביך. בשביל זה העזרה קיימת.\", \"אחר צהריים בחינם בפארק יכול להיות היום הכי טוב בשבוע.\", \"גרמת לכסף להספיק עוד שבוע. זה דורש כישרון אמיתי.\", \"דאגות כסף מעייפות. את סוחבת הרבה, ואת עדיין כאן.\", \"שתית היום כוס מים. תתחילי משם.\", \"כולם יצאו מהדלת. אולי הנעליים לא התאימו. עדיין ניצחון.\", \"עשית את שיחת הטלפון שחששת ממנה. זה היה אמיץ.\", \"צחקת היום. תחזיקי בזה.\", \"ארוחה חמה, חולצה נקייה, סיפור לפני השינה. דברים קטנים מצטברים לילדות.\", \"היום היית טובה למישהו, גם אם זו היית רק את.\", \"התקדמות, לא שלמות. היום התקדמת.\", \"סיימת דבר אחד מהרשימה. זה אחד יותר מכלום.\", \"את אמא טובה. העובדה שאת דואגת לגבי זה מראה כמה אכפת לך.\", \"את יותר ממה שאת מספיקה לעשות ביום אחד.\", \"הילדים שלך לא צריכים אמא מושלמת. הם צריכים אותך, ויש להם אותך.\", \"תהיי סבלנית עם עצמך כמו שאת סבלנית עם הילדים שלך.\", \"מותר לך לתפוס מקום, לרצות דברים ולהחזיק בחלומות משלך.\", \"טעות לא מוחקת אהבה. מחר זו התחלה חדשה.\", \"את כל העולם של מישהו, ואת גם אישה בפני עצמה.\", \"זה בסדר לא לאהוב כל רגע. את עדיין יכולה לאהוב את הילדים שלך בכל הלב.\", \"אין דרך נכונה אחת להיות אמא. גם הדרך שלך לגיטימית.\", \"כמו בתנוחת העץ, זה בסדר להתנדנד. את יכולה למצוא שוב את שיווי המשקל.\", \"תעמידי את הרגליים יציב כמו בתנוחת ההר. את יציבה יותר ממה שאת מרגישה.\", \"לוחמת שתיים: רגליים חזקות, ידיים פתוחות. זו את, מול השבוע הזה.\", \"שאיפה עד ארבע, נשיפה עד ארבע. את כאן, ואת מסתדרת יפה.\", \"תתמתחי לרוחב כמו כוכב. מותר לך לתפוס מקום.\", \"סקוואט רחב ונמוך קשה להחזיק. גם יום ארוך. ואת מחזיקה.\", \"את יכולה להתכופף כמו חרמש של ירח ועדיין לעמוד.\", \"את לא צריכה להגיע לבהונות עדיין. כל מתיחה קטנה נחשבת.\", \"תנוחת המשולש: יד אחת למטה, יד אחת למעלה. תישארי מקורקעת ותמשיכי להימתח.\", \"כבר מאוחר. מה שלא נעשה היום יכול לחכות למחר.\", \"ערה עם התינוק בשעה כזאת? הרבה אמהות ערות איתך עכשיו.\", \"הבית שקט. הרגע הזה שלך. תנשמי.\", \"עברת את היום. זה כל מה שהיום היה צריך.\", \"אם הראש לא מפסיק לעבוד הלילה, תכתבי את זה ותני לזה לחכות לבוקר.\", \"תני לעיניים לנוח. מחר תוכלי להתחיל מחדש.\", \"חגים יכולים להיות קשים וגם שמחים. מה שהעונה הזאת מרגישה לך, זה בסדר.\", \"השולחן לא צריך להיות מושלם. מה שחשוב זה האנשים מסביבו.\", \"אם השנה חסר לך מישהו ליד השולחן, תהיי עדינה עם הלב שלך.\", \"תודה, אמא, על כל ארוחה, כל הסעה וכל חיבוק.\", \"את לא חייבת לארח, לאפות או לחייך כל הזמן. חג פשוט הוא עדיין חג.\", \"המתנה הכי טובה שהילדים שלך מקבלים השנה היא זמן איתך.\", \"חגיגה קטנה מלאה באהבה גם היא. לא צריך הרבה כסף כדי שתהיה מיוחדת.\", \"ימים קרים, חיבוקים חמים. את המקום החם בבית שלך.\", \"זה בסדר לדלג על חלק מהלחץ של החגים. שקט זה גם מתנה.\", \"אם העונה הזאת כבדה עלייך השנה, את לא לבד. יום אחד בכל פעם.\"]";D.body.appendChild(e)})();
